<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Models\ContentPage;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
class PageManagerController extends Controller {private function data(Request $r,?ContentPage $page=null):array{return $r->validate(['title'=>'required|string|max:180','slug'=>'required|alpha_dash|max:180|unique:content_pages,slug,'.($page?->id??'NULL'),'intro'=>'nullable|string|max:1000','body'=>'nullable|string|max:100000','status'=>'required|in:draft,review,scheduled,published,unpublished,archived','locale'=>'required|string|max:10','template'=>'required|string|max:80','navigation_visible'=>'nullable|boolean','scheduled_for'=>'nullable|date','meta_title'=>'nullable|string|max:180','meta_description'=>'nullable|string|max:500']);}private function snapshot(ContentPage $page,string $reason):void{$page->revisions()->create(['user_id'=>auth()->id(),'version'=>((int)$page->revisions()->max('version'))+1,'snapshot'=>$page->fresh()->toArray(),'reason'=>$reason]);}public function index(Request $r){$pages=ContentPage::withTrashed()->when($r->status,fn($q,$v)=>$v==='trash'?$q->onlyTrashed():$q->where('status',$v))->when($r->q,fn($q,$v)=>$q->where(fn($x)=>$x->where('title','like','%'.$v.'%')->orWhere('slug','like','%'.$v.'%')))->latest()->paginate(25)->withQueryString();return view('admin.pages.index',compact('pages'));}public function store(Request $r){$d=$this->data($r);$page=ContentPage::create($this->normalise($r,$d));$this->snapshot($page,'Created');return back()->with('success','Page created.');}public function update(Request $r,ContentPage $page){$this->snapshot($page,'Before update');$page->update($this->normalise($r,$this->data($r,$page)));return back()->with('success','Page updated.');}private function normalise(Request $r,array $d):array{$meta=['title'=>$d['meta_title']??null,'description'=>$d['meta_description']??null];unset($d['meta_title'],$d['meta_description']);return $d+['navigation_visible'=>$r->boolean('navigation_visible'),'meta'=>$meta,'published_at'=>$d['status']==='published'?now():null,'archived_at'=>$d['status']==='archived'?now():null];}public function action(Request $r,ContentPage $page,string $action){abort_unless(in_array($action,['duplicate','publish','unpublish','archive','trash'],true),404);if($action==='duplicate'){$copy=$page->replicate();$copy->uuid=Str::uuid();$copy->title.=' Copy';$copy->slug.='-'.Str::lower(Str::random(6));$copy->status='draft';$copy->published_at=null;$copy->save();$this->snapshot($copy,'Duplicated');}elseif($action==='trash'){$this->snapshot($page,'Moved to trash');$page->delete();}else{$status=['publish'=>'published','unpublish'=>'unpublished','archive'=>'archived'][$action];$this->snapshot($page,Str::headline($action));$page->update(['status'=>$status,'published_at'=>$status==='published'?now():null,'archived_at'=>$status==='archived'?now():null]);}return back()->with('success','Page action completed.');}public function restore(int $page){$record=ContentPage::onlyTrashed()->findOrFail($page);$record->restore();$this->snapshot($record,'Restored');return back()->with('success','Page restored.');}public function destroy(int $page){ContentPage::onlyTrashed()->findOrFail($page)->forceDelete();return back()->with('success','Page permanently deleted.');}}
